 if skill_path:settings.append({'path':skill_path.as_posix(),'enabled':True})
 args=options('A')
 args[1]='skills.config=['+','.join('{path='+json.dumps(s['path'])+',enabled='+str(s['enabled']).lower()+'}' for s in settings)+']'
 return args

def probe(workspace,args,log):
 err=log.with_suffix('.stderr.txt').open('w',encoding='utf-8')
 try:p=subprocess.Popen(['codex','app-server','--stdio']+args,stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=err,text=True,encoding='utf-8')
 except BaseException:
  err.close();raise
 q=queue.Queue()
 def read():
  try:
   for s in p.stdout:q.put(s)
  finally:q.put(None)
 reader=threading.Thread(target=read,daemon=True);reader.start()
 def rpc(n,method,params):
  p.stdin.write(json.dumps({'id':n,'method':method,'params':params})+'\n');p.stdin.flush()
  deadline=time.monotonic()+30
  while True:
   remaining=deadline-time.monotonic()
   if remaining<=0:raise TimeoutError('App-server RPC timed out: '+method)
   try:line=q.get(timeout=remaining)
   except queue.Empty:raise TimeoutError('App-server RPC timed out: '+method) from None
   if line is None:raise RuntimeError('App-server closed stdout; stderr: '+str(log.with_suffix('.stderr.txt')))
   obj=json.loads(line)
   if obj.get('id')==n:
    if 'error' in obj:raise RuntimeError('App-server RPC error: '+json.dumps(obj['error'],ensure_ascii=False))
    return obj
 try:
  rpc(1,'initialize',{'clientInfo':{'name':'intent_v2_eval','version':'1.0'}})
  r=rpc(2,'skills/list',{'cwds':[str(workspace)],'forceReload':True})
  log.write_text(json.dumps(r,ensure_ascii=False,indent=2),encoding='utf-8')
  return [s for s in r['result']['data'][0]['skills'] if s['enabled']]
 finally:
  if p.poll() is None:p.terminate()
  try:p.wait(timeout=3)
  except subprocess.TimeoutExpired:p.kill();p.wait()
  reader.join(timeout=3)
  p.stdin.close();p.stdout.close();err.close()

@contextmanager
def run_record(folder):
 started=time.monotonic()
 status={'exit_code':None,'stage':'setup','process_started':False}
 try:yield status
 except Exception as exc:
  if status['exit_code'] is not None:status['process_exit_code']=status['exit_code']
  status.update(exit_code=None,error={'type':type(exc).__name__,'message':str(exc)})
 except BaseException as exc:
  status.update(exit_code=None,error={'type':type(exc).__name__,'message':str(exc)})
  raise
 finally:
  status.setdefault('wall_seconds',round(time.monotonic()-started,2))
  status['elapsed_seconds']=round(time.monotonic()-started,2)
  (folder/'run.json').write_text(json.dumps(status,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')

def execute(command,prompt,folder,status,env,timeout,cwd=None):
 status['stage']='execution';started=time.monotonic()
 with (folder/'events.jsonl').open('w',encoding='utf-8') as out,(folder/'stderr.txt').open('w',encoding='utf-8') as err:
  try:
   result=subprocess.run(command,input=prompt,text=True,encoding='utf-8',stdout=out,stderr=err,timeout=timeout,env=env,cwd=cwd)
   status.update(exit_code=result.returncode,process_started=True)
   if result.returncode:status['error']={'type':'ProcessExit','message':'Process exited with code '+str(result.returncode)+'; see events.jsonl and stderr.txt.'}
  except subprocess.TimeoutExpired:
   status.update(timeout=True,process_started=True,error={'type':'TimeoutExpired','message':'Execution exceeded '+str(timeout)+' seconds.'})
  finally:status['wall_seconds']=round(time.monotonic()-started,2)

def isolated_config(workspace,skill_path,log):
 args=config(skill_path)
 enabled=probe(workspace,args,log)
 def matches():
  return len(enabled)==1 and pathlib.Path(enabled[0]['path']).resolve()==skill_path.resolve() if skill_path else not enabled
 if not matches():
  # Host updates can add skill paths after the historical inventory was captured.
  observed=json.loads(log.read_text(encoding='utf-8'))['result']['data'][0]['skills']
  known={s['path'] for s in inventory}
  additions=[s for s in observed if s['path'] not in known]
  if additions:
   shutil.copy2(log,log.with_name(log.stem+'-before-refresh.json'))
   inventory.extend(additions)
   args=config(skill_path)
   enabled=probe(workspace,args,log)
 assert matches(),enabled
 return args

def execution_environment(log):
 env=os.environ.copy()
 env['PATH']=str(pathlib.Path(sys.executable).parent)+os.pathsep+env.get('PATH','')
 resolved=shutil.which('python',path=env['PATH'])
 assert resolved and pathlib.Path(resolved).resolve()==pathlib.Path(sys.executable).resolve(),resolved
 check=subprocess.run([resolved,'-I','-c','import sys; print(sys.executable); print(sys.version.split()[0])'],env=env,capture_output=True,text=True,encoding='utf-8',check=True)
 log.write_text(json.dumps({'policy':'Evaluator interpreter directory prepended to child PATH equally for all arms; host environment unchanged.','python':resolved,'probe':check.stdout.splitlines(),'limits':'Checks direct child process only; generated-tool runtime success must still be observed. Do not compare with historical unprepared environments as causal Skill gains.'},ensure_ascii=False,indent=2),encoding='utf-8')
 return env

def run(round_id,case,arm):
 assert case in PROMPTS and arm in ['A','G','V1','V2']
 folder=OUT/'runs'/round_id/case/arm
 folder.mkdir(parents=True,exist_ok=False)
 with run_record(folder) as status:
  workspace=folder/'workspace';workspace.mkdir()
  fixtures(case,workspace,arm);skill_path=None
  if arm in SOURCES:
   dest=workspace/'.agents/skills/intent-compiler'
   shutil.copytree(SOURCES[arm],dest)
   skill_path=dest/'SKILL.md'
  status['stage']='skill_isolation'
  args=isolated_config(workspace,skill_path,folder/'skills.json')
  prompt=PROMPTS[case]+BOUNDARY
  if arm=='G':prompt=GENERIC+prompt
  if skill_path:prompt='$intent-compiler\n'+prompt
  command=['codex','exec','--ignore-user-config','--ephemeral','--skip-git-repo-check','--json','-m','gpt-6.1-sol','-s','workspace-write','-C',str(workspace),'-o',str(folder/'response.md')]+args+['-']
  (folder/'invocation.json').write_text(json.dumps({'argv':command,'stdin':prompt,'source':str(SOURCES.get(arm,''))},ensure_ascii=False,indent=2),encoding='utf-8')
  status['stage']='environment'
  env=execution_environment(folder/'environment.json')
  execute(command,prompt,folder,status,env,900)
 print(round_id,case,arm,status)

if __name__=='__main__':run(*sys.argv[1:])
